<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('rewards.view');$status=strtoupper(trim((string)input('status')));$hunt=(int)input('hunt_id');$user=(int)input('user_id');$where=[];$params=[];if(in_array($status,['PENDING','APPROVED','REJECTED'],true)){$where[]='r.status=?';$params[]=$status;}if($hunt){$where[]='r.hunt_id=?';$params[]=$hunt;}if($user){$where[]='r.user_id=?';$params[]=$user;}$sql=$where?' WHERE '.implode(' AND ',$where):'';$s=db()->prepare('SELECT r.*,u.name user_name,u.mobile,h.title hunt_title,hs.distance_meters,hs.risk_level,hs.device_id,hs.ip_address,w.transaction_id FROM rewards r JOIN users u ON u.id=r.user_id JOIN hunts h ON h.id=r.hunt_id JOIN hunt_scans hs ON hs.id=r.scan_id LEFT JOIN wallet_transactions w ON w.id=r.wallet_transaction_id'.$sql.' ORDER BY r.id DESC LIMIT 300');$s->execute($params);$items=$s->fetchAll();$hunts=db()->query('SELECT id,title FROM hunts ORDER BY title')->fetchAll();$pageTitle='Hunt rewards';$pageSubtitle='Review scan evidence before any wallet credit is created';require APP_ROOT.'/includes/header.php';?><section class="panel"><form class="filters" method="get"><input type="number" min="1" name="user_id" value="<?=e($user?:'')?>" placeholder="User ID"><select name="hunt_id"><option value="">All hunts</option><?php foreach($hunts as $h):?><option value="<?=e($h['id'])?>" <?=$hunt===$h['id']?'selected':''?>><?=e($h['title'])?></option><?php endforeach?></select><select name="status"><option value="">All statuses</option><?php foreach(['PENDING','APPROVED','REJECTED'] as $v):?><option <?=$status===$v?'selected':''?>><?=e($v)?></option><?php endforeach?></select><button class="btn">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Reward</th><th>User</th><th>Hunt</th><th>Amount</th><th>GPS / risk</th><th>Device / IP</th><th>Status</th><th>Ledger</th><th></th></tr></thead><tbody><?php foreach($items as $r):?><tr><td><?=e($r['reward_id'])?><br><small><?=e($r['created_at'])?></small></td><td><?=e($r['user_name'])?><br><small>#<?=e($r['user_id'])?> · <?=e($r['mobile'])?></small></td><td><?=e($r['hunt_title'])?></td><td><?=money($r['amount'])?></td><td><?=e($r['distance_meters'])?> m<br><span class="risk <?=strtolower(e($r['risk_level']))?>"><?=e($r['risk_level'])?></span></td><td><?=e($r['device_id'])?><br><small><?=e($r['ip_address'])?></small></td><td><span class="badge <?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></td><td><?=e($r['transaction_id']??'—')?></td><td><a class="btn small secondary" href="<?=e(app_url('/admin/rewards/view.php?id='.$r['id']))?>">Review</a></td></tr><?php endforeach?></tbody></table><?php if(!$items):?><div class="empty">No rewards match these filters.</div><?php endif?></div></section><?php require APP_ROOT.'/includes/footer.php';
